"""Build the full research notebook without overwriting an executed artifact."""
import nbformat as nbf
from agentic_rag.artifacts import ROOT,read

def main():
    path=ROOT / "notebooks/01_complete_agentic_rag_research.ipynb"
    if path.exists():
        old=nbf.read(path,as_version=4)
        if any(c.get("outputs") or c.get("execution_count") is not None for c in old.cells):
            raise FileExistsError("Executed notebook is protected; preserve it in .local before rebuilding")
    cells=[]
    def section(title,prose,code):
        cells.extend([nbf.v4.new_markdown_cell("## "+title+"\n\n"+prose),nbf.v4.new_code_cell(code.strip())])
    section("Agentic RAG and tool-augmented reasoning", "This third study in the RAG series tests whether a controller should retrieve again, choose another search tool, or stop. Fixed retrieval is a serious comparator. All reported values come from retained experiment traces; no-retrieval and oracle-document controls help distinguish retrieval gains from remaining context and generation limits.", '''from pathlib import Path
import sys, json, inspect, hashlib
ROOT=Path.cwd()
if ROOT.name=='notebooks': ROOT=ROOT.parent
if ROOT.name!='Agentic RAG': ROOT=ROOT/'Agentic RAG'
sys.path.insert(0,str(ROOT/'src'))
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
from IPython.display import display
get_ipython().run_line_magic('matplotlib','inline')
from agentic_rag.artifacts import read,sha,digest,fingerprint
from agentic_rag.evaluation import score,aggregate,paired_interval
OUT=ROOT/'reports'
(OUT/'figures').mkdir(parents=True,exist_ok=True)
metrics=read(OUT/'metrics.json')
reliability=read(OUT/'reliability.json')
intervals=read(OUT/'paired-intervals.json')
config=read(ROOT/'configs/study.json')
freeze=read(OUT/'selection-freeze.json')
names=['hotpot','squad']
strategies=['fixed','adaptive','plan','agent','verify','none','oracle']
def records(label,name,split='evaluation'):
    manifest=read(ROOT/f'data/manifests/{label}-{name}-{split}.json')
    return [read(ROOT/e['path']) for e in manifest['rows']]
def scores(label,name,split='evaluation'):
    return read(ROOT/f'data/scores/{label}-{name}-{split}.json')
def frame(labels,names=names,split='evaluation'):
    return pd.DataFrame([dict(dataset=n,strategy=s,**metrics[f'{s}-{n}-{split}']) for n in names for s in labels])
plt.rcParams.update({'figure.figsize':(10,4),'axes.spines.top':False,'axes.spines.right':False})
display(pd.DataFrame(config.items(),columns=['setting','value']))''')
    section("Research questions and comparison logic", "The primary question is whether dynamic evidence gathering improves answer F1. Secondary questions concern evidence recall, tool selection, plan quality, verification-induced abstention, unnecessary retrieval and inference costs. The comparisons change control logic while fixing the main answer model. They do not assume that more steps help.", "display(frame(strategies)[['dataset','strategy','n','groups']])")
    section("Related methods and design boundaries", "[ReAct](https://arxiv.org/abs/2210.03629) motivates interacting with evidence tools; [IRCoT](https://aclanthology.org/2023.acl-long.557/) motivates evidence-dependent queries. [Adaptive-RAG](https://aclanthology.org/2024.naacl-long.389/) studies complexity-based routing, whereas this rule baseline checks source diversity and lexical coverage. [Self-RAG](https://arxiv.org/abs/2310.11511) learns reflection tokens; our external NLI gate is a different mechanism. This study does not reproduce those papers' training procedures or benchmark results.", "display(pd.DataFrame([['Fixed','No control-model overhead'],['Rules','Deterministic sufficiency proxy'],['Plan','Two actions before observations'],['Agent','Observe and choose again'],['Verify','External generated-claim check']],columns=['strategy','design choice']))")
    section("Reference findings and preservation", "Project 1's fusion gains and reranking losses motivate controlled tests. Project 2 found that practical FLAN-T5-base could outperform structured Qwen generation. Its citation and NLI limitations motivate separate source-label and claim-support diagnostics here. The prior files remain unchanged.", "preserved=read(OUT/'preservation.json')\nassert all(sha(ROOT.parent/p)==h for p,h in preserved.items())\nprint('Preserved prior-project files:',len(preserved))\nprint('Cleanup:',read(OUT/'cleanup.json'))")
    section("Hardware and executable environment", "The environment audit measures the actual host. Available memory changes during the run. Local CUDA overlays and model snapshots are reused without modifying the earlier projects. No paid API is used.", "environment=read(OUT/'environment.json')\ndisplay(pd.DataFrame([(k,v) for k,v in environment.items() if k not in ['packages','reusable']],columns=['item','observed']))\ndisplay(pd.DataFrame(environment['reusable']))\nprint(read(OUT/'runtime-environment.json')['actual_imports'])")
    section("Dataset provenance and alternatives", "HotpotQA distractor is the primary multihop benchmark. SQuAD 2.0 contributes genuine unanswerable questions. All previous SQuAD development articles had been touched, so the fresh complementary study uses article-disjoint partitions of the public training release. MuSiQue and 2Wiki were reviewed but not acquired. These local partitions are not official test results.", "sources=read(ROOT/'sources.lock.json')\nfor source in sources:\n    path=ROOT/('data/raw/squad-train.json' if source['name']=='squad' else 'data/raw/hotpot.json')\n    assert sha(path)==source['sha256']\ndisplay(pd.DataFrame(sources)[['name','url','bytes','sha256','license']])")
    section("Partitions and prior exposure", "Group allocation precedes question sampling. Development selects the reference; validation is a diagnostic check; evaluation stays untouched until the freeze. Prior question IDs are excluded and SQuAD is grouped by article. HotpotQA can still share pages across questions. The published sampling record can reconstruct exact partitions on a fresh checkout.", "validation=read(OUT/'data-validation.json')\npartitions={n:read(ROOT/f'data/partitions/{n}.json') for n in names}\nsplit_rows=[]\nfor name in names:\n    for split,values in validation[name]['partitions'].items():\n        assert digest(partitions[name][split])==values['hash']\n        split_rows.append(dict(dataset=name,split=split,**{k:v for k,v in values.items() if k!='ids'}))\ndisplay(pd.DataFrame(split_rows))")
    section("Question types and answerability", "HotpotQA bridge and comparison questions pose different evidence needs. SQuAD class prevalence matters because abstention alone can score well. The class counts below retain the original labels.", "eda=pd.DataFrame([dict(dataset=n,split=s,kind=r['kind'],words=len(r['question'].split()),documents=len(r['documents'])) for n in names for s,rows in partitions[n].items() for r in rows])\ndisplay(eda.groupby(['dataset','split','kind']).size().rename('count').to_frame())")
    section("Exploratory question distribution", "Question length and candidate count characterize this bounded study. SQuAD supplies one paragraph per question, so selecting another retrieval backend does not create another document of evidence.", "fig,axes=plt.subplots(1,2,figsize=(11,4))\nfor name,group in eda.groupby('dataset'):\n    axes[0].hist(group.words,bins=20,alpha=.5,label=name)\n    axes[1].hist(group.documents,bins=10,alpha=.5,label=name)\naxes[0].set_xlabel('Question words'); axes[1].set_xlabel('Candidate documents')\nfor ax in axes: ax.legend()\nplt.tight_layout(); fig.savefig(OUT/'figures/question-distribution.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Annotation validation and duplicate checks", "Original labels are retained. Out-of-range supporting facts are reported and omitted only from the sentence-recall denominator. Question and candidate-body duplicates are counted, and split separation is checked. HotpotQA groups questions, so document reuse across partitions is measured rather than hidden. SQuAD answer offsets are validated against original paragraphs during loading.", "display(pd.DataFrame([dict(dataset=n,original_questions=v['original_questions'],previous_questions_excluded=v['previous_questions_excluded'],available_questions=v['available_questions'],duplicate_questions=v['duplicate_question_texts'],invalid_facts=len(v['invalid_facts'])) for n,v in validation.items()]))\ndisplay(pd.DataFrame(read(OUT/'data-structure.json')).T)\nfor name in names:\n    sets=[{r['group'] for r in rows} for rows in partitions[name].values()]\n    assert all(not sets[i]&sets[j] for i in range(3) for j in range(i))")
    section("Structured agent state and action validation", "The controller stores evidence, steps, call counts, tokens, failures and stage times. JSON actions can only dispatch registered read-only tools. Malformed outputs, unknown tools, repeated actions and budget exhaustion are handled in Python rather than delegated to instruction following.", "from agentic_rag.controller import Action,State,Controller,SEARCH,LOOKUP\nprint(inspect.getsource(Action))\nprint(inspect.getsource(State))")
    section("Evidence store and passage provenance", "Passages retain original titles, sentence offsets and deterministic IDs. Deduplication operates on passage IDs. Source titles identify documents within a question; they are not globally unique corpus identifiers.", "from agentic_rag.tools import Index,EvidenceStore\nfrom agentic_rag.data import task\nexample=partitions['hotpot']['evaluation'][0]\nindex=Index(task(example))\ndisplay(pd.DataFrame([dict(id=p.id,document=p.document,sentence_indices=p.sentence_indices,words=len(p.text.split())) for p in index.passages]).head(12))\nprint(inspect.getsource(EvidenceStore))")
    section("Search tools and ranking formulas", "BM25 uses positive Robertson IDF with k1=1.5 and b=0.75. Dense search uses normalized BGE-small embeddings. Hybrid search fuses sparse and dense ranks with constant 60, and MiniLM reranks up to 12 fused candidates. Fetch and title-link lookup use exact source IDs.", "from agentic_rag.tools import BM25Okapi\nprint(inspect.getsource(BM25Okapi))\nprint(inspect.getsource(Index.execute))")
    section("Graph navigation and evidence expansion", "Edges are deterministic title mentions in source passages. They support navigation without claiming that a semantic relationship is verified. Expansion returns bounded passages around the best query-overlap anchor inside a chosen document. It introduces no gold evidence labels.", "print('Example title-mention links:',{k:v for k,v in index.links.items() if v})\ngraph_stats=[]\nfor row in partitions['hotpot']['evaluation']:\n    graph=Index(task(row)).links\n    graph_stats.append(dict(nodes=len(graph),edges=sum(map(len,graph.values())),has_edge=any(graph.values())))\ndisplay(pd.DataFrame(graph_stats).describe())\nprint('Graph construction uses source text only:',inspect.getsource(Index.__init__))")
    section("Five distinct control strategies", "Fixed RAG retrieves once. Rules expand when document diversity or question-token coverage is low. Plan-and-execute commits to up to two actions before reading evidence. The reactive agent observes tool output before choosing again. Verification-guided control tests generated claims, permits further gathering and can abstain.", "print(inspect.getsource(Controller.run))")
    section("Model snapshots and inference formats", "Each snapshot is pinned by revision and file hash. FLAN-T5-base answers all primary conditions. Planner candidates include FLAN and two Qwen sizes. BGE, MiniLM reranking and DeBERTa NLI serve separate roles. Greedy Qwen decoding is an experimental choice, different from its recommended sampling setup.", "models=read(ROOT/'models.lock.json')\ndisplay(pd.DataFrame([dict(alias=a,model=r['id'],revision=r['revision'],license=r['license'],bytes=r['bytes']) for a,r in models.items()]))\nprint(read(OUT/'resources.json'))")
    section("Development-only planner comparison", "The initial pilot exposed wrong lookup fields and repeated actions. Before held-out evaluation, the prompt gained candidate titles and explicit schemas, no-source outputs were gated, and planner utility was revised to include evidence usefulness. A contradictory single-object example in the plan-array prompt was also corrected and checked on eight development questions. Earlier revisions remain local. The final model pilot uses eight development questions per dataset and cannot establish a general model ranking.", "planner=read(OUT/'planner-selection.json')\nprint('Criterion:',planner['criterion']); print('Selected:',planner['selected'])\ndisplay(pd.DataFrame([dict(model=a,dataset=n,**v) for a,ds in planner['results'].items() for n,v in ds.items()])[['model','dataset','n','f1','evidence_recall','invalid_actions','calls','p50_ms']])\ndisplay(pd.DataFrame(read(OUT/'plan-schema-probe.json')).T[['n','calls','invalid_actions','f1']])")
    section("Exploratory answer-model comparison", "The same fixed retrieval backend is used for the small answer-model check. Tokenizers and input ceilings differ, and the shared context setting can select different passages. FLAN remains the prespecified primary generator; this is an exploratory system comparison.", "comparison=read(OUT/'generator-comparison.json')\nprint(comparison['policy'])\ndisplay(pd.DataFrame([dict(model=a,dataset=n,**v) for a,ds in comparison['results'].items() for n,v in ds.items()])[['model','dataset','n','f1','answered','model_support','p50_ms']])")
    section("Retrieval selection on development data", "Four retrieval backends compete on 32 development questions per dataset with the answer model fixed. The pooled F1 winner becomes the fixed reference. Development choices never use evaluation answers.", "display(frame(['retrieval_bm25','retrieval_dense','retrieval_hybrid','retrieval_rerank'],split='development')[['dataset','strategy','n','f1','evidence_recall','p50_ms']])\nprint('Selected retrieval:',freeze['retrieval'])")
    section("Validation and protocol freeze", "Validation measures the frozen design without tuning thresholds. The freeze precedes every final-evaluation checkpoint. All primary conditions share the source fingerprint; raw generations record their actual prompts and settings.", "display(frame(['fixed','adaptive','plan','agent','verify'],split='validation')[['dataset','strategy','f1','answered','calls','invalid_actions']])\nassert freeze['source_identity']==fingerprint()\nprint('Freeze:',freeze['timestamp_utc'],freeze['freeze_hash'])")
    section("Main answer comparison", "The full held-out comparison uses 128 questions per dataset. EM measures exact normalized answers; token F1 gives partial credit. Performance can worsen under extra planning or verification, and no method is assumed to dominate.", "main=frame(strategies)\ndisplay(main[['dataset','strategy','n','em','f1','answered','selective_em']])")
    section("Bridge, comparison and answerability slices", "The original question-type labels identify where aggregate gains or losses occur. HotpotQA bridge and comparison questions have different evidence needs. For SQuAD, separate answerable and unanswerable rows distinguish answer quality from class-prior effects. These smaller slices are descriptive and should be read with their sample sizes.", "type_metrics=read(OUT/'question-type-metrics.json')\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,kind=k,**v) for n in names for s in ['fixed','adaptive','plan','agent','verify'] for k,v in type_metrics[f'{s}-{n}-evaluation'].items()])[['dataset','strategy','kind','n','em','f1','answered','evidence_recall']])")
    section("Answer quality figure", "The bars show point estimates on matched question sets. Paired intervals below describe uncertainty in differences. The oracle-document row still has a finite context and the same generator.", "fig,axes=plt.subplots(1,2,figsize=(12,4))\nfor ax,name in zip(axes,names):\n    main[main.dataset==name].set_index('strategy')[['em','f1']].plot.bar(ax=ax,ylim=(0,1),title=name)\nplt.tight_layout(); fig.savefig(OUT/'figures/answer-quality.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Evidence-document and supporting-fact recall", "Packed-context recall measures original gold titles retained with the final answer result, rather than every source ever returned. Separate returned-evidence and memory recall reveal retrieval gains lost through deduplication, context limits or final budget abstention. HotpotQA sentence recall requires complete original sentence containment.", "display(main[['dataset','strategy','evidence_recall','supporting_fact_recall','citation_recall']])\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,returned_recall=reliability[f'{s}-{n}-evaluation']['returned_evidence_recall'],memory_recall=reliability[f'{s}-{n}-evaluation']['memory_evidence_recall']) for n in names for s in ['fixed','adaptive','plan','agent','verify']]))")
    section("Evidence quality figure", "The HotpotQA document and sentence diagnostics show whether additional control finds useful evidence before generation. SQuAD's single paragraph makes document recall a limited discriminator.", "main[main.dataset=='hotpot'].set_index('strategy')[['evidence_recall','supporting_fact_recall']].plot.bar(ylim=(0,1))\nplt.ylabel('Recall in packed context'); plt.tight_layout(); plt.gcf().savefig(OUT/'figures/evidence-recall.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Citation validity and source-label agreement", "Citation assignment is a post hoc overlap heuristic. The validity flag describes the proposal before final abstention: its IDs must occur in packed context. The separate uncited-answer count checks final accepted outputs. Precision and recall compare original source labels. These checks do not establish model reliance or entailment, and one lexical citation can omit another document needed for a multihop answer.", "display(main[['dataset','strategy','citation_precision','citation_recall','citation_valid']])\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,uncited_answers=reliability[f'{s}-{n}-evaluation']['answer_without_valid_citation']) for n in names for s in strategies]))")
    section("Actual generated claims and model support", "A separate FLAN call rewrites each proposal as a declarative claim. DeBERTa scores it against the cited passage. The controller score defaults to zero for unscored proposals; conditional averages below use retained final claims only. Intermediate NLI probabilities are not logged, although generation calls and cumulative verifier time are preserved. Claim rewriting, truncation and question mismatch limit these model estimates; they remain separate from evidence annotations.", "display(main[['dataset','strategy','model_support','model_contradiction','claim_contains_answer']])\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,claim_proposals=reliability[f'{s}-{n}-evaluation']['claim_proposals'],mean_scored_entailment=reliability[f'{s}-{n}-evaluation']['mean_nli_entailment_on_claims'],accepted_claim_entailment=reliability[f'{s}-{n}-evaluation']['mean_nli_entailment_on_accepted_claims']) for n in names for s in ['fixed','adaptive','plan','agent','verify']]))\nprint(inspect.getsource(Controller.answer))")
    section("Missing and conflicting evidence diagnostics", "Missing annotated documents can be counted, but a missing label does not prove the answer is unsupported. The controller checks NLI only against its assigned citation. This separate post-run replay checks the claim against every packed passage and flags simultaneous entailment and contradiction signals. The frozen controller never sees these extra checks. They reveal possible missed conflicts for review and are not independently verified contradictions.", "conflicts=read(OUT/'conflict-diagnostics.json')\nprint(conflicts['scope'])\ndisplay(pd.DataFrame(conflicts['results']).T)\nprint('Replay time, separate from benchmark latency (ms):',conflicts['replay_ms'])")
    section("Citation-window case review", "The assistant review inspects real proposed answers, generated claims and their assigned source windows. It selects two nonempty proposals for each dataset and strategy, excludes previously selected questions, and prefers rejected verification proposals. The review is unblinded to reference answers and has no independent human rater. Its counts describe these cases, not a population faithfulness estimate. Hashes prevent reuse of labels after answers or evidence change.", "review=read(OUT/'support-review.json')\nprint(review['annotator']); print(review['selection']); print(review['criteria'])\nprint('Unique questions:',review['unique_questions']); print('All reviewed proposals:',review['counts']); print('Accepted proposals:',review['accepted_counts'])\ndisplay(pd.DataFrame(review['cases']))")
    section("Verification and abstention", "The verification agent can reject an answer-string match or accept an irrelevant entailed claim. An answer-string match is not by itself evidence of support, and an EM mismatch can miss valid aliases. Coverage and selective EM expose the acceptance tradeoff. SQuAD's original unanswerable cases allow a false-answer rate; always-abstain helps identify prevalence-driven gains.", "display(main[['dataset','strategy','f1','answered','selective_em','false_answer_rate']])\ndisplay(pd.DataFrame([dict(dataset=n,**read(OUT/f'always-abstain-{n}.json')) for n in names]))\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,high_support_em_mismatch=reliability[f'{s}-{n}-evaluation']['high_support_answer_em_mismatch'],rejected_proposals=reliability[f'{s}-{n}-evaluation']['rejected_proposals'],rejected_exact_matches=reliability[f'{s}-{n}-evaluation']['rejected_exact_match_proposals']) for n in names for s in ['fixed','agent','verify']]))")
    section("Risk and coverage", "Selective EM is descriptive of the accepted subset rather than accuracy on all questions. It should be read with the number of accepted answers and the full-set F1.", "fig,ax=plt.subplots()\nfor name in names:\n    group=main[(main.dataset==name)&main.strategy.isin(['fixed','adaptive','plan','agent','verify'])]\n    ax.scatter(group.answered,group.selective_em,label=name)\n    for _,r in group.iterrows(): ax.annotate(r.strategy,(r.answered,r.selective_em))\nax.set(xlabel='Answer coverage',ylabel='Selective exact match',xlim=(0,1),ylim=(0,1)); ax.legend(); fig.savefig(OUT/'figures/risk-coverage.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Paired uncertainty", "Bootstrap resampling keeps answers paired and resamples SQuAD articles as clusters. Intervals use 2,000 replicates, are pointwise and are not adjusted for multiple comparisons. Small cluster counts can leave wide intervals.", "paired=pd.DataFrame([dict(configuration=k,**v) for k,v in intervals.items() if any(k==f'{s}-{n}-evaluation' for s in ['adaptive','plan','agent','verify','none','oracle'] for n in names)])\ndisplay(paired)")
    section("Matched difference figure", "Differences are relative to fixed RAG on the same 128 questions. The figure shows the direction and uncertainty of each strategy's answer-F1 change.", "fig,ax=plt.subplots(figsize=(10,6))\nx=np.arange(len(paired)); mid=paired.delta.to_numpy(); low=paired.low.to_numpy(); high=paired.high.to_numpy()\nax.errorbar(mid,x,xerr=np.vstack([mid-low,high-mid]),fmt='o'); ax.axvline(0,color='grey',linestyle='--')\nax.set_yticks(x,paired.configuration); ax.set_xlabel('F1 difference from fixed'); plt.tight_layout(); fig.savefig(OUT/'figures/paired-f1.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Search budgets, context and evidence memory", "The ablations change one setting at a time on the same first 32 evaluation questions. A one-step agent still spends planning inference; it is not the fixed pipeline. Deduplication affects packed context as well as storage.", "budget_labels=['steps1','calls2','context280','no_dedup']\ndisplay(frame(budget_labels)[['dataset','strategy','n','f1','evidence_recall','calls','tokens','p50_ms']])")
    section("Registry and stopping ablations", "Search-only and BM25-only registries test whether exposing more tools helps. Verification thresholds 0 and 0.8 change acceptance and stopping relative to the prespecified 0.5 rule. These held-out sensitivity results do not select another final model.", "display(frame(['search_only','bm25_only','verify_zero','verify_high'])[['dataset','strategy','n','f1','answered','calls','invalid_actions']])")
    section("Bad-tool outputs and recovery", "The first actual call can return nothing, passages from the tail of the candidate order, or a synthetic instruction attack. Tail-order passages are an irrelevant-result proxy and may coincidentally contain gold evidence. Each perturbation uses the same underlying question set; comparisons with an unperturbed subset are matched.", "display(frame(['empty_first','irrelevant_first','injection_first'])[['dataset','strategy','n','f1','evidence_recall','additional_evidence_gain','calls','invalid_actions']])\ndisplay(pd.DataFrame([dict(configuration=k,**v) for k,v in intervals.items() if any(k.startswith(x) for x in ['empty_first','irrelevant_first','injection_first'])]))")
    section("Tool choices and reliability", "Successful dispatch can return empty evidence. Invalid-action counts include rejected schema fields, repeated actions and invalid source IDs; they are distinct from backend exceptions. Safe budget termination is not a runaway loop, though it can stop too early.", "display(main[['dataset','strategy','calls','steps','tool_success_rate','invalid_action_rate','empty_calls','budget_terminated']])\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,**reliability[f'{s}-{n}-evaluation']['tool_distribution']) for n in names for s in ['plan','agent','verify']]).fillna(0))")
    section("Unnecessary calls and retrieval gains", "Duplicate-evidence frequency is a conservative waste proxy. The matched one-step contrast also counts extra calls with identical answers or no F1 gain. Recovery means a later call retrieved an annotated document after the first-result intervention. These diagnostics are not independent causal-necessity labels.", "display(main[['dataset','strategy','calls','redundant_calls','additional_evidence_gain']])\ndisplay(pd.DataFrame(read(OUT/'call-utility.json')).T)\ndisplay(pd.DataFrame(read(OUT/'retrieval-recovery.json')).T)\ndisplay(pd.DataFrame([dict(dataset=n,strategy=s,reasons=reliability[f'{s}-{n}-evaluation']['controller_stop_reasons']) for n in names for s in strategies]))")
    section("A real multi-step trace", "The example is selected from actual HotpotQA agent traces by executed call count, without changing the outcome. The trace retains returned passages and failed actions so that evidence lookups can be inspected. This is an illustrative post hoc case, not a representative estimate.", "agent_traces=records('agent','hotpot')\ntrace=max(agent_traces,key=lambda r:r['state']['calls'])\nrow=next(r for r in partitions['hotpot']['evaluation'] if r['id']==trace['id'])\nprint('Question:',row['question']); print('Reference:',row['answers']); print('Answer:',trace['answer']); print('Stop:',trace['reason'])\ndisplay(pd.DataFrame(trace['state']['trace']))\nprint('Plan model outputs:',[g['text'] for g in trace['state']['generations'] if g['stage']=='planning'])")
    section("Where agentic control harms answers", "This matched case selects the largest fixed-to-agent F1 loss in the recorded HotpotQA evaluation. Better evidence recall is not sufficient if planning, context packing or generation discards the useful fact. Source windows and actual outputs remain visible for diagnosis.", "fixed_scores=scores('fixed','hotpot'); agent_scores=scores('agent','hotpot')\nloss=max(range(len(fixed_scores)),key=lambda i:fixed_scores[i]['f1']-agent_scores[i]['f1'])\nfixed_trace=records('fixed','hotpot')[loss]; agent_trace=agent_traces[loss]\nrow=partitions['hotpot']['evaluation'][loss]\nprint(row['question'],row['answers']); print('Fixed:',fixed_trace['answer']); print('Agent:',agent_trace['answer'])\ndisplay(pd.DataFrame(agent_trace['context'])); display(pd.DataFrame(agent_trace['state']['trace']))")
    section("Verification rejection example", "The first held-out rejected proposal illustrates a gate decision. It does not by itself show that the gate was correct. Inspect the generated claim, source text, answer annotation and NLI score together.", "rejected=[r for r in records('verify','hotpot') if r.get('rejected_answer')]\nif rejected:\n    case=rejected[0]; row=next(r for r in partitions['hotpot']['evaluation'] if r['id']==case['id'])\n    print(row['question'],row['answers']); print('Rejected:',case['rejected_answer']); print('Claim:',case['claim']); print('NLI:',case['support'])\n    display(pd.DataFrame(case['context']))\nelse: print('No nonempty rejected proposal in this recorded condition.')")
    section("Latency decomposition", "Times include actual inference and tool work. The fixed comparator receives the same claim/NLI diagnostics. Per-question end-to-end time includes indexing; model loading is separate. Checkpoint reload speed is not reported as inference latency.", "display(main[['dataset','strategy','planning_ms','retrieval_ms','verification_ms','generation_ms','p50_ms','p95_ms','tokens']])")
    section("Runtime cost figure", "Mean stage costs reveal where orchestration adds work. These are sequential, warm-run observations with uncontrolled background activity; they are not throughput estimates for a serving system.", "fig,axes=plt.subplots(1,2,figsize=(12,4))\nfor ax,name in zip(axes,names):\n    stage=main[(main.dataset==name)&main.strategy.isin(['fixed','adaptive','plan','agent','verify'])].set_index('strategy')\n    (stage[['planning_ms','retrieval_ms','verification_ms','generation_ms']]/1000).plot.bar(stacked=True,ax=ax,title=name)\n    ax.set_ylabel('Mean seconds')\nplt.tight_layout(); fig.savefig(OUT/'figures/stage-costs.png',dpi=160,bbox_inches='tight'); plt.show()")
    section("Memory and loading costs", "Process peak working set and CUDA allocated/reserved peaks cover whole sequential processes and co-resident models. They do not isolate a single method's memory. Stage-specific resource files preserve observations across separate research commands.", "resources=[dict(stage=p.stem,**read(p)) for p in (OUT/'resource-stages').glob('*.json')]\nresource_frame=pd.DataFrame(resources)\ndisplay(resource_frame[['stage','device','rss_bytes','peak_working_set_bytes','cuda_peak_allocated_bytes','cuda_peak_reserved_bytes','generator_load_ms']])\nprint('Maximum observed CUDA allocation GiB:',resource_frame.cuda_peak_allocated_bytes.max()/2**30)")
    section("Experiment-to-report consistency", "Replaying the scorer on retained traces protects aggregate tables from transcription errors. Row hashes verify the annotated input. A separate standard-library implementation checks answer EM/F1 against each dataset's metric conventions. Neither check certifies model correctness or replaces independent evidence annotation.", "checked=0\nfor name in names:\n    annotations={r['id']:r for r in partitions[name]['evaluation']}\n    for strategy in strategies:\n        rows=[score(r,annotations[r['id']]) for r in records(strategy,name)]\n        assert aggregate(rows)==metrics[f'{strategy}-{name}-evaluation']\n        checked+=len(rows)\nprint('Primary question results recomputed from trace files:',checked)\nprint('Separate answer-metric implementation:',read(OUT/'metric-convention-audit.json'))")
    section("Tests, security scope and recovery", "The pre-publication tests cover action validation, finite transitions, budgets, dispatch, deduplication, citations, deterministic behavior, malformed outputs, unavailable services and injected instructions. The final suite also checks the public notebook after its creation. Separate uncached model probes exercise five workflows twice and check simple NLI pairs; a real CLI smoke test checks the command path. These synthetic probes are not benchmark or comprehensive security evidence.", "import xml.etree.ElementTree as ET\ntest_root=ET.parse(OUT/'tests-notebook.xml').getroot()\ndisplay(pd.DataFrame([s.attrib for s in test_root.iter('testsuite')]))\nprobes=read(OUT/'workflow-probes.json')\nprint(probes['scope']); display(pd.DataFrame(probes['results'])[['strategy','answer','repeat_signature_equal','calls','tokens']])\nprint('NLI label map:',probes['nli_labels']); display(pd.DataFrame(probes['nli_semantic_probes']))\nprint('CLI smoke:',read(OUT/'cli-smoke.json'))\nprint('Retained failed/interrupt records:',read(OUT/'execution-ledger.json')['failed_records'])")
    section("Reproduce and resume", "The scripts acquire and verify data/models, reconstruct the published sampling lock, run staged experiments, rebuild reports, execute this notebook in a clean kernel, and create its output-free public copy. Completed unchanged question runs are reused. Source/config/model changes create new cache identities. Never replace the local executed notebook to regenerate the public copy.", "print('Source identity:',fingerprint())\nprint('Freeze source identity:',freeze['source_identity'])\nprint('Completed stage ledger:',read(OUT/'execution-ledger.json'))\nassert read(OUT/'experiment-provenance.json')['source_identity']==fingerprint()")
    observed=read(ROOT/'reports/metrics.json')
